252	    /**
253	     * A claim's figure under any late charge: the due fixed when settled, else the one bound by a
254	     * statement (not while PENDING), else the live due; null when it has none.
255	     */
256	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
257	        if (claim.getStatus() == ClaimStatus.SETTLED) {
258	            return claim.getSettledDue();
259	        }
260	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
261	                : due(sheetId, person, claim);
262	    }
