264	    /** A claim's figure with its late charge on the sheet's today added on top; null when it has none. */
265	    public BigDecimal charged(String sheetId, Person person, Claim claim) {
266	        return LateCharge.withCharge(sheets.sheet(sheetId), claim, figure(sheetId, person, claim));
267	    }
