274	    @Transactional
275	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
276	            String corrects) {
277	        Person person = person(sheetId, personId);
278	        LocalDate dated = dateOrToday(sheetId, date);
279	        periods.refuseIfClosed(sheetId, dated);
280	        refuseIfRetired(person, dated);
281	        String corrected = corrected(sheetId, personId, amount, corrects);
282	        RollupService.Snapshot before = rollup.snapshot(sheetId);
283	        Claim claim = new Claim(sheetId, personId, amount, dated,
284	                dated.plusDays(sheets.sheet(sheetId).termsFor(person.gradeOn(dated), dated)), note, corrected);
285	        logStatus(sheetId, user, person, claim);
286	        Claim added = claims.saveAndFlush(claim);
287	        audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, added));
288	        rollup.recordChanges(sheetId, user, before);
289	        return added;
