293	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
294	            String corrects) {
295	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
296	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
297	        if (claim.getStatus() != ClaimStatus.DRAFT) {
298	            throw new ResponseStatusException(HttpStatus.CONFLICT,
299	                    "A " + claim.getStatus() + " claim cannot be edited.");
300	        }
301	        LocalDate dated = dateOrToday(sheetId, date);
302	        periods.refuseIfClosed(sheetId, claim.getDate());
303	        periods.refuseIfClosed(sheetId, dated);
304	        refuseIfRetired(person(sheetId, claim.getPersonId()), dated);
305	        String corrected = corrected(sheetId, claim.getPersonId(), amount, corrects);
306	        RollupService.Snapshot before = rollup.snapshot(sheetId);
307	        claim.setAmount(amount);
308	        claim.setDate(dated);
309	        claim.setNote(note);
310	        claim.setCorrects(corrected);
311	        Claim saved = claims.saveAndFlush(claim);
312	        audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
313	        rollup.recordChanges(sheetId, user, before);
314	        return saved;
315	    }
