317	    /**
318	     * Move a claim to a new status, refused (409) when its current status does not allow it, and
319	     * refused (403) when the user who opened it tries to settle it. A clerk settling one whose
320	     * figure is above the sheet's clerk limit makes it PENDING instead.
321	     */
322	    @Transactional
323	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
324	        return changeStatus(sheetId, user, id, next, null, false);
325	    }
326	
327	    /**
328	     * Approve a PENDING claim: it becomes SETTLED, its due fixed at its live figure with its late
329	     * charge on the sheet's today. Refused (409) when not PENDING, and (403) for a clerk or the
330	     * user who opened it.
331	     */
332	    @Transactional
333	    public Claim approve(String sheetId, String user, long id) {
334	        return changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null, true);
335	    }
336	
337	    /**
338	     * Reject a PENDING claim with a reason: it is OPEN again, bound again by the last statement if
339	     * that statement included it. Refused (409) when not PENDING, and (403) for a clerk.
340	     */
341	    @Transactional
342	    public Claim reject(String sheetId, String user, long id, String reason) {
343	        return changeStatus(sheetId, user, id, ClaimStatus.OPEN, reason, true);
344	    }
345	
346	    /** Move a claim to a new status; {@code review} for a steward's approval or rejection of a PENDING claim. */
347	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
348	            boolean review) {
349	        // lock the sheet's numbering before reading the claim, so a claim is opened (and numbered) once
350	        if (next == ClaimStatus.OPEN) {
351	            sheets.lock(sheetId);
352	        }
353	        RollupService.Snapshot before = rollup.snapshot(sheetId);
354	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
355	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
356	        ClaimStatus was = claim.getStatus();
357	        // only a steward's review moves a PENDING claim on, other than voiding it
358	        if (!was.canBecome(next) || (next != ClaimStatus.VOID && review != (was == ClaimStatus.PENDING))) {
359	            throw new ResponseStatusException(HttpStatus.CONFLICT,
360	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
361	        }
362	        periods.refuseIfClosed(sheetId, claim.getDate());
363	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
364	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
365	                    "The user who opened a claim cannot " + (review ? "approve" : "settle") + " it.");
366	        }
367	        if (review && !isSteward(sheetId, user)) {
368	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
369	                    "Only a steward can approve or reject a PENDING claim.");
370	        }
371	        Person person = person(sheetId, claim.getPersonId());
372	        // settling fixes the figure with its late charge as it stands on the sheet's today (a
373	        // PENDING claim's figure is live)
374	        BigDecimal settling = next == ClaimStatus.SETTLED ? charged(sheetId, person, claim) : null;
375	        if (next == ClaimStatus.SETTLED && !review && aboveClerkLimit(sheetId, user, settling)) {
376	            next = ClaimStatus.PENDING;
377	            settling = null;
378	        }
379	        claim.setStatus(next);
380	        if (next == ClaimStatus.OPEN && !review) {
381	            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDate()));
382	            claim.setOpenedBy(user);
383	        } else if (next == ClaimStatus.SETTLED) {
384	            claim.setSettledDue(settling);
385	        }
386	        logStatus(sheetId, user, person, claim);
387	        Claim saved = claims.saveAndFlush(claim);
388	        String event = switch (next) {
389	            case OPEN -> review ? "CLAIM_REJECTED" : "CLAIM_OPENED";
390	            case PENDING -> "CLAIM_PENDING";
391	            case SETTLED -> review ? "CLAIM_APPROVED" : "CLAIM_SETTLED";
392	            case VOID -> "CLAIM_VOIDED";
393	            case DRAFT -> throw new IllegalStateException();
394	        };
395	        audit.recordOnCommit(record(event, sheetId, user, person, saved)
396	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
397	                + (next == ClaimStatus.SETTLED ? " due=" + dueText(saved.getSettledDue()) : "")
398	                + (reason != null ? " reason=" + reason : ""));
399	        rollup.recordChanges(sheetId, user, before);
400	        return saved;
401	    }
402	
403	    /**
404	     * Re-settle a SETTLED claim: fix its due again at the figure it would have on the sheet's today
405	     * as an open claim bound by no statement, with its late charge. Refused (403) for anyone but a
406	     * steward, (409) for a claim that is not SETTLED and (423) when dated inside a closed period.
407	     */
408	    @Transactional
409	    public Claim resettle(String sheetId, String user, long id) {
410	        if (!isSteward(sheetId, user)) {
411	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim.");
412	        }
413	        RollupService.Snapshot before = rollup.snapshot(sheetId);
414	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
415	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
416	        if (claim.getStatus() != ClaimStatus.SETTLED) {
417	            throw new ResponseStatusException(HttpStatus.CONFLICT,
418	                    "A " + claim.getStatus() + " claim cannot be re-settled.");
419	        }
420	        periods.refuseIfClosed(sheetId, claim.getDate());
421	        Person person = person(sheetId, claim.getPersonId());
422	        BigDecimal old = claim.getSettledDue();
423	        BigDecimal settling = LateCharge.withChargeAsOpen(sheets.sheet(sheetId), claim, due(sheetId, person, claim));
424	        claim.setSettledDue(settling);
425	        logStatus(sheetId, user, person, claim);
426	        Claim saved = claims.saveAndFlush(claim);
427	        audit.recordOnCommit(record("CLAIM_RESETTLED", sheetId, user, person, saved)
428	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
429	                + " old=" + dueText(old) + " new=" + dueText(settling));
430	        rollup.recordChanges(sheetId, user, before);
431	        return saved;
432	    }
433	
434	    /**
435	     * Move a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and
436	     * date, is unbound from any statement (live again until its new person's next statement), and
437	     * is listed first under its new person. Refused (403) for a clerk, (409) for a SETTLED or VOID
438	     * claim or a move to the person it is already on, (400) for a correction (it must stay with
439	     * the claim it corrects), (423) when dated inside a closed period and (422) when dated after
440	     * the new person's retirement date.
441	     */
442	    @Transactional
443	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
444	        if (!isSteward(sheetId, user)) {
445	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can move a claim.");
446	        }
447	        RollupService.Snapshot before = rollup.snapshot(sheetId);
448	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
449	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
450	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
451	            throw new ResponseStatusException(HttpStatus.CONFLICT,
452	                    "A " + claim.getStatus() + " claim cannot be moved.");
453	        }
454	        Person from = person(sheetId, claim.getPersonId());
455	        Person to = person(sheetId, toPersonId);
456	        if (from.getId().equals(to.getId())) {
457	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already on that person.");
458	        }
459	        if (claim.isCorrection()) {
460	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A correction cannot be moved.");
461	        }
462	        periods.refuseIfClosed(sheetId, claim.getDate());
463	        refuseIfRetired(to, claim.getDate());
464	        claim.setPersonId(to.getId());
465	        claim.bind(false, null);
466	        claims.saveAndFlush(claim);
467	        claims.listFirst(claim.getId());
468	        Claim saved = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
469	        audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
470	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
471	                + " from=" + from.getName() + " to=" + to.getName());
472	        rollup.recordChanges(sheetId, user, before);
473	        return saved;
474	    }
475	
476	    /** What a bulk open did: how many claims were opened and how many refused, and the claims opened. */
477	    public record BulkOpened(int opened, int refused, List<Claim> claims) {
478	    }
479	
480	    /**
481	     * Open the given claims together, in list order (the order people were added, newest claim
482	     * first within a person), so they are numbered in that order. A claim that cannot be opened
483	     * (not on the sheet, not DRAFT, or dated inside a closed period) is refused and left as it is.
484	     */
485	    @Transactional
486	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> ids) {
487	        List<Claim> selected = inListOrder(sheetId, ids);
488	        int refused = (int) ids.stream().distinct().count() - selected.size();
489	        List<Claim> opened = new ArrayList<>();
490	        for (Claim claim : selected) {
491	            if (claim.getStatus() != ClaimStatus.DRAFT || periods.isClosed(sheetId, claim.getDate())) {
492	                refused++;
493	                continue;
494	            }
495	            opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
496	        }
497	        return new BulkOpened(opened.size(), refused, opened);
498	    }
499	
500	    /** What a bulk settle did: how many claims were settled (or made PENDING) and how many refused, and the claims changed. */
501	    public record BulkSettled(int settled, int refused, List<Claim> claims) {
502	    }
503	
504	    /**
505	     * Settle the given claims together, in list order (the order people were added, newest claim
506	     * first within a person), each by exactly the rules of settling one claim. A claim a clerk's
507	     * settle makes PENDING counts as settled; a claim that cannot be settled is refused and left
508	     * as it is.
509	     */
510	    @Transactional
511	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> ids) {
512	        List<Claim> selected = inListOrder(sheetId, ids);
513	        int refused = (int) ids.stream().distinct().count() - selected.size();
514	        List<Claim> settled = new ArrayList<>();
515	        for (Claim claim : selected) {
516	            try {
517	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
518	            } catch (ResponseStatusException refusedOne) {
519	                // every refusal is checked before the claim is changed, so it is left as it is
520	                refused++;
521	            }
522	        }
523	        return new BulkSettled(settled.size(), refused, settled);
524	    }
525	
526	    /** The given claims on the sheet in list order: people as added, newest claim first within a person. */
527	    private List<Claim> inListOrder(String sheetId, Collection<Long> ids) {
528	        Map<Long, Integer> personOrder = new HashMap<>();
529	        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
530	        for (int i = 0; i < listed.size(); i++) {
531	            personOrder.put(listed.get(i).getId(), i);
532	        }
533	        return ids.stream().distinct()
534	                .flatMap(id -> claims.findByIdAndSheetId(id, sheetId).stream())
535	                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
536	                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
537	                .toList();
538	    }
539	
540	    /**
541	     * The due on a claim's amount at the rate for the person's grade in force on the claim's date,
542	     * rounded to the cent as the claim rounds (see {@link Rounding}) and raised to the floor in force on the claim's date (a correction's is not); null with no
543	     * rate in force then.
544	     */
545	    public BigDecimal due(String sheetId, Person person, Claim claim) {
546	        Sheet sheet = sheets.sheet(sheetId);
547	        RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
548	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
549	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding))
550	                .map(due -> claim.isCorrection() ? due : due.max(sheet.floorOn(claim.getDate())))
551	                .orElse(null);
552	    }
553	
554	    /** The date a claim rounds by: its own, or for a correction that of the claim it corrects. */
555	    private LocalDate roundingDate(String sheetId, Claim claim) {
556	        if (!claim.isCorrection() || claim.getCorrects() == null) {
557	            return claim.getDate();
558	        }
559	        return Rounding.dateOf(claim, claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()));
560	    }
561	
562	    /** Log the claim's status as it is now: by the user, on the sheet's today, with its due as computed now. */
563	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
564	        claim.log(new ClaimLogEntry(claim.getStatus(), user, sheets.today(sheetId),
565	                dueText(charged(sheetId, person, claim))));
566	    }
567	
568	    private static String dueText(BigDecimal due) {
569	        return due == null ? "n/a" : due.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
570	    }
571	
572	    /** Whether the user is a clerk settling a claim whose figure is above the sheet's clerk limit. */
573	    private boolean aboveClerkLimit(String sheetId, String user, BigDecimal figure) {
574	        BigDecimal limit = sheets.clerkLimit(sheetId);
575	        return figure != null && limit != null && figure.compareTo(limit) > 0 && !isSteward(sheetId, user);
576	    }
577	
578	    private boolean isSteward(String sheetId, String user) {
579	        return Role.STEWARD.equals(roles.roleOf(sheetId, user));
580	    }
581	
582	    /**
583	     * The number a claim corrects: none unless its amount is negative, when it must name the number
584	     * of a SETTLED claim of the same person, else it is refused (400).
585	     */
586	    private String corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
587	        if (amount.signum() >= 0) {
588	            return null;
589	        }
590	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
591	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
592	        if (!settled) {
593	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
594	                    "A negative amount must correct a SETTLED claim of the same person, by its number.");
595	        }
596	        return corrects;
597	    }
598	
599	    /** Refuse (422) a claim dated after its person's retirement date. */
600	    private static void refuseIfRetired(Person person, LocalDate date) {
601	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
602	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
603	                    "That claim's date is after its person's retirement date.");
604	        }
605	    }
606	
607	    private Person person(String sheetId, long personId) {
608	        return people.findByIdAndSheetId(personId, sheetId)
609	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
610	    }
611	
612	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
613	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName() + " amount="
614	                + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString() + " date=" + claim.getDate();
615	    }
616	
617	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
618	        return date != null ? date : sheets.today(sheetId);
619	    }
620	}
