        firstValueFrom(this.http.post<Claim[]>('/api/claims/list', { sheet })),
        firstValueFrom(this.http.post<StatementSummary[]>('/api/statements/list', { sheet })),
        firstValueFrom(this.http.post<PatronLink[]>('/api/people/patrons/list', { sheet })),
